<section><div class="page-heading"><div><a class="back-link" href="/sa/stores">← Stores</a><p class="eyebrow">Tenant store</p><h1><?= e($store['name']) ?></h1><p class="muted">/<?= e($store['slug']) ?> · Created <?= e($store['created_at']) ?></p></div><div class="admin-page-actions"><a class="button secondary" href="<?= e(store_absolute_url($store)) ?>" target="_blank" rel="noopener">Open storefront</a><span class="badge <?= strtolower($store['status']) ?>"><?= e($store['status']) ?></span></div></div><div class="admin-metrics compact"><article><span>Products</span><strong><?= e($metrics['products']) ?></strong></article><article><span>Categories</span><strong><?= e($metrics['categories']) ?></strong></article><article><span>Customers</span><strong><?= e($metrics['customers']) ?></strong></article><article><span>Orders</span><strong><?= e($metrics['orders']) ?></strong><small><?= e($store['currency_code']) ?> <?= e($metrics['order_value']) ?> value</small></article></div><div class="admin-detail-grid"><section class="panel"><div class="panel-title"><h2>Store control</h2><span>Publication status</span></div><dl class="admin-definition"><div><dt>Current status</dt><dd><?= e($store['status']) ?></dd></div><div><dt>Country / currency</dt><dd><?= e($store['country_code']) ?> / <?= e($store['currency_code']) ?></dd></div><div><dt>WhatsApp</dt><dd><?= e($store['whatsapp_number']) ?></dd></div><?php if($store['suspended_at']):?><div><dt>Suspended at</dt><dd><?= e($store['suspended_at']) ?></dd></div><?php endif ?></dl><form method="post" action="/sa/stores/<?= e($store['id']) ?>/status" data-confirm="<?= $store['status']==='SUSPENDED'?'Reactivate this store?':'Suspend this store?' ?>" data-confirm-message="Suspension replaces the public storefront with a neutral unavailable page. Reactivation restores the previous Draft or Active state."><?= csrf_field() ?><input type="hidden" name="action" value="<?= $store['status']==='SUSPENDED'?'REACTIVATE':'SUSPEND' ?>"><button class="button <?= $store['status']==='SUSPENDED'?'primary':'danger' ?>" type="submit"><?= $store['status']==='SUSPENDED'?'Reactivate store':'Suspend store' ?></button></form></section><section class="panel"><div class="panel-title"><h2>Subscription</h2><span><?= e($store['subscription_status']??'Unconfigured') ?></span></div><dl class="admin-definition"><div><dt>Plan</dt><dd><?= e($store['plan_name']??'None') ?></dd></div><div><dt>Provider</dt><dd><?= e($store['provider']??'—') ?></dd></div><div><dt>Period ends</dt><dd><?= e($store['current_period_ends_at']??'No fixed end') ?></dd></div><div><dt>Grace ends</dt><dd><?= e($store['grace_ends_at']??'—') ?></dd></div></dl><form class="admin-inline-form" method="post" action="/sa/stores/<?= e($store['id']) ?>/plan" data-confirm="Change this store plan?" data-confirm-message="This is a privileged manual override. It activates the selected plan immediately and records an audit event."><?= csrf_field() ?><label>Plan<select name="plan_code"><?php foreach($plans as$plan):?><option value="<?= e($plan['code']) ?>" <?= $store['plan_code']===$plan['code']?'selected':'' ?> <?= !$plan['is_active']&&$store['plan_code']!==$plan['code']?'disabled':'' ?>><?= e($plan['name']) ?><?= !$plan['is_active']?' (inactive)':'' ?></option><?php endforeach ?></select></label><label>Paid period days<input type="number" name="period_days" value="30" min="1" max="3650"></label><button class="button secondary" type="submit">Apply plan override</button></form></section></div><div class="admin-split"><section class="panel flush"><div class="list-head"><span>Members</span><small><?= count($members) ?></small></div><?php if(!$members):?><div class="empty-inline padded">No store memberships.</div><?php else:?><div class="admin-list"><?php foreach($members as$row):?><a href="/sa/merchants/<?= e($row['id']) ?>"><div><strong><?= e($row['name']) ?> · <?= e($row['role']) ?></strong><small><?= e($row['email']) ?></small></div><span class="badge <?= strtolower($row['membership_status']) ?>"><?= e($row['membership_status']) ?></span></a><?php endforeach ?></div><?php endif ?></section><section class="panel flush"><div class="list-head"><span>Recent orders</span><small><?= count($orders) ?></small></div><?php if(!$orders):?><div class="empty-inline padded">No orders for this store.</div><?php else:?><div class="admin-list"><?php foreach($orders as$row):?><div><div><strong><?= e($row['reference']) ?> · <?= e($row['customer_name']) ?></strong><small><?= e($row['placed_at']) ?></small></div><span><?= e($row['currency_code']) ?> <?= e($row['total']) ?></span></div><?php endforeach ?></div><?php endif ?></section></div><section class="panel"><div class="panel-title"><h2>Subscription event history</h2><span>Latest <?= count($events) ?></span></div><?php if(!$events):?><div class="empty-inline">No subscription events recorded.</div><?php else:?><div class="event-list"><?php foreach($events as$row):?><div><strong><?= e($row['event_type']) ?></strong><small><?= e(($row['from_plan']??'—').' → '.($row['to_plan']??'—')) ?> · <?= e(($row['from_status']??'—').' → '.($row['to_status']??'—')) ?> · <?= e($row['created_at']) ?></small></div><?php endforeach ?></div><?php endif ?></section></section>
